from collections import deque
def enclosures(I):
    h,w=I.shape
    seen=np.zeros_like(I,bool); q=deque()
    for i in range(h):
        for j in (0,w-1):
            if I[i,j]==0 and not seen[i,j]: seen[i,j]=True;q.append((i,j))
    for j in range(w):
        for i in (0,h-1):
            if I[i,j]==0 and not seen[i,j]: seen[i,j]=True;q.append((i,j))
    while q:
        a,b=q.popleft()
        for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
            x,y=a+da,b+db
            if 0<=x<h and 0<=y<w and I[x,y]==0 and not seen[x,y]:
                seen[x,y]=True;q.append((x,y))
    return [(a,b) for a in range(h) for b in range(w) if I[a,b]==0 and not seen[a,b]]
