import numpy as np, collections
def solve(I):
    I=np.array(I); h,w=I.shape; O=I.copy()
    seen=np.zeros_like(I,bool)
    for i in range(h):
        for j in range(w):
            if I[i,j]==1 and not seen[i,j]:
                st=[(i,j)];seen[i,j]=True;cells=[]
                while st:
                    a,b=st.pop();cells.append((a,b))
                    for da in(-1,0,1):
                        for db in(-1,0,1):
                            x,y=a+da,b+db
                            if 0<=x<h and 0<=y<w and I[x,y]==1 and not seen[x,y]:
                                seen[x,y]=True;st.append((x,y))
                rs=[r for r,_ in cells]; cls=[c for _,c in cells]
                for a in range(min(rs),max(rs)+1):
                    for b in range(min(cls),max(cls)+1):
                        if I[a,b]==1: continue
                        if (a==min(rs) or a==max(rs) or b==min(cls) or b==max(cls)): O[a,b]=2
                        else: O[a,b]=3
    return O.tolist()
