                    for da in(-1,0,1):
                        for db in(-1,0,1):
                            x,y=a+da,b+db
                            if 0<=x<h and 0<=y<w and A[x,y]==1 and not seen[x,y]:
                                seen[x,y]=True;st.append((x,y))
                out.append(cells)
