def feats(I,O):
    I=np.array(I);O=np.array(O);h,w=I.shape
    cs=comps(I)
    info=[]
    for c in cs:
        rs=[r for r,_ in c];cls=[cc for _,cc in c]
        r0,r1,c0,c1=min(rs),max(rs),min(cls),max(cls)
        # candidate rule B: expanded perimeter
        exp=set()
        for a in range(max(0,r0-1),min(h,r1+2)):
            for b in range(max(0,c0-1),min(w,c1+2)):
                if (a in(r0-1,r1+1) or b in(c0-1,c1+1)) and I[a,b]!=1:
                    exp.add((a,b))
        twos=[(a,b) for a in range(h) for b in range(w) if O[a,b]==2 and I[a,b]==0]
        threes=[(a,b) for a in range(h) for b in range(w) if O[a,b]==3 and I[a,b]==0]
        mism_b=twos-not exp
        mism_a=exp-set(twos)
        # interior zeros (inside bbox not on perimeter)
        inter=[(a,b) for a in range(r0+1,r1) for b in range(c0+1,c1) if I[a,b]==0]
        mism_i=[p for p in inter if O[p[0],p[1]]!=3]
        info.append((len(c),(r1-r0+1)*(c1-c0+1),len(twos),len(threes),len(mism_b),len(mism_a),len(mism_i)))
    return info
