def f(I,O=None,verbose=False):
    I=np.array(I);h,w=I.shape;O=I.copy()
    for c in comps(I):
        rs=[r for r,_ in c];cls=[cc for _,cc in c]
        r0,r1,c0,c1=min(rs),max(rs),min(cls),max(cls)
        ring=[(a,b) for a in range(r0-1,r1+2) for b in range(c0-1,c1+2)
              if not(r0<=a<=r1 and c0<=b<=c1)]
        inter=[(a,b) for a in range(r0+1,r1) for b in range(c0+1,c1)]
        for a,b in ring:
            if I[a,b]==0: O[a,b]=2
        for a,b in inter:
            if I[a,b]==0: O[a,b]=3
        if verbose:
            twos=len([p for p in ring if I[p[0],p[1]]==0])
            ints=len([p for p in inter if I[p[0],p[1]]==0])
            print('comp size',len(c),'bbox',(r1-r0+1)*(c1-c0+1),'ring0=',twos,'interior0=',ints)
    return O.tolist()
