def solve(I):
    I=np.array(I);H,W=I.shape
    dirs=[(1,0),(-1,0),(0,1),(0,-1)]
    # flood from border over zeros, blocked by 1s
    reach=np.zeros((H,W),bool);q=deque()
    for y in range(H):
        for x in range(W):
            if I[y,x]==0 and (y in(0,H-1) or x in(0,W-1)):
                reach[y,x]=True;q.append((y,x))
    while q:
        y,x=q.popleft()
        for dy,dx in dirs:
            ny,nx=y+dy,x+dx
            if 0<=ny<H and 0<=nx<W and I[ny,nx]==0 and not reach[ny,nx]:
                reach[ny,nx]=True;q.append((ny,nx))
    C=comps(I)
    O=I.copy()
    for cs in C:
        ys=[p[0] for p in cs];xs=[p[1] for p in cs]
        r0,r1,c0,c1=min(ys),max(ys),min(xs),max(xs)
        S=set(cs)
        # interior zeros of this ring
        for y in range(r0+1,r1):
            for x in range(c0+1,c1):
                if I[y,x]==0:
                    if not reach[y,x]: O[y,x]=3
                    elif min(max(abs(y-a),abs(x-b)) for a,b in S)==1: O[y,x]=2
                    else: O[y,x]=0
    return O.tolist()
