def flood(I, allow_diag_between_zeros_only=True):
    H,W=I.shape; reach=set();qq=deque()
    for y in range(H):
        for x in [0,W-1]:
            if I[y,x]==0: reach.add((y,x));qq.append((y,x))
    for x in range(W):
        for y in [0,H-1]:
            if I[y,x]==0 and (y,x) not in reach: reach.add((y,x));qq.append((y,x))
    while qq:
        y,x=qq.popleft()
        for dy,dx in DIRS8:
            ny,nx=y+dy,x+dx
            if 0<=ny<H and 0<=nx<W and I[ny,nx]==0 and (ny,nx) not in reach:
                if allow_diag_between_zeros_only and dy!=0 and dx!=0 and I[y+dy,x]!=0 and I[y,x+dx]!=0:
                    continue
                reach.add((ny,nx));qq.append((ny,nx))
    return reach
