def feats(I,y,x):
    H,W=I.shape
    out={}
    # cardinal ray counts (unblocked to edge)
    def blocked(yy,xx,dy,dx):
        yy+=dy;xx+=dx
        while 0<=yy<H and 0<=xx<W:
            if I[yy,xx]==1: return True
            yy+=dy;xx+=dx
        return False
    ncard=sum(1 for dy,dx in [(1,0),(-1,0),(0,1),(0,-1)] if not blocked(y,x,dy,dx))
    ndiag=sum(1 for dy,dx in [(1,1),(1,-1),(-1,1),(-1,-1)] if not blocked(y,x,dy,dx))
    # diagonal flood reachability (corner flood)
    # BFS from border cells through zeros, diagonal moves allowed unless both orthogonal neighbors are walls
    reach=set();qq=collections.deque()
    for y2 in range(H):
        for x2 in [0,W-1]:
            if I[y2,x2]==0 and (y2,x2) not in reach: reach.add((y2,x2));qq.append((y2,x2))
    for x2 in range(W):
        for y2 in [0,H-1]:
            if I[y2,x2]==0 and (y2,x2) not in reach: reach.add((y2,x2));qq.append((y2,x2))
    while qq:
        y2,x2=qq.popleft()
        for dy,dx in DIRS8:
            ny,nx=y2+dy,x2+dx
            if 0<=ny<H and 0<=nx<W and I[ny,nx]==0 and (ny,nx) not in reach:
                if dy!=0 and dx!=0 and I[y2+dy,x2]!=0 and I[y2,x2+dx]!=0: continue
                reach.add((ny,nx));qq.append((ny,nx))
    out['corner_reach']= (y,x) in reach
    # strict enclosure: all four cardinal rays blocked AND not reachable via corner-flood... use 'corner_reach' complement
    out['manh_dist']=(abs(y-min(xx for xx in range(W))) ) # dummy
    out['ncomp']=None
    return out
