    for y in range(H):
        for x in [0,W-1]:
            if I[y,x]==0 and (y,x) not in seen: seen.add((y,x));qq.append((y,x))
    for x in range(W):
        for y in [0,H-1]:
            if I[y,x]==0 and (y,x) not in seen: seen.add((y,x));qq.append((y,x))
    while qq:
        y,x=qq.popleft()
        for dy,dx in [(1,0),(-1,0),(0,1),(0,-1)]:
            ny,nx=y+dy,x+dx
            if 0<=ny<H and 0<=nx<W and I[ny,nx]==0 and (ny,nx) not in seen:
                seen.add((ny,nx));qq.append((ny,nx))
    return seen
def solve(I):
    I=np.array(I); H,W=I.shape
    out=[[0]*W for _ in range(H)]
    outer=outside_strict(I)
    for y in range(H):
        for x in range(W):
            if I[y,x]!=0: out[y][x]=int(I[y,x]); continue
            inner=(y,x) not in outer
