D4=[(1,0),(-1,0),(0,1),(0,-1)]
def orthdist(I):
    H,W=I.shape; dist=np.full((H,W),99); q=collections.deque()
    for y in range(H):
        for x in range(W):
            if I[y,x]==0 and (y in(0,H-1) or x in(0,W-1)):
                dist[y,x]=0; q.append((y,x))
    while q:
        cy,cx=q.popleft()
        for dy,dx in D4:
            ny,nx=cy+dy,cx+dx
            if 0<=ny<H and 0<=nx<W and I[ny,nx]==0 and dist[ny,nx]>dist[cy,cx]+1:
                dist[ny,nx]=dist[cy,cx]+1; q.append((ny,nx))
    return dist
